function choiceToText(t,w){if(/プロフィールの共通点/.test(t))return `マッチングありがとうございます！プロフィールの${common(w)[0]||'趣味'}が気になりました。よろしくお願いします。`;if(/雰囲気を具体的に褒め/.test(t))return '写真の雰囲気が素敵ですね。自然体な感じがいいなと思いました！';if(/休日の予定/.test(t))return '今度の休日は何か予定ありますか？';if(/長文/.test(t))return '自分の趣味や休日の過ごし方について、色々お話ししますね。';if(/ペース/.test(t))return 'そうなんですね！無理せずゆっくりお話しできたら嬉しいです。';if(/共感/.test(t))return 'それいいですね！自分も似た経験があって、すごくわかります。';if(/日常/.test(t))return '休日は家でゆっくりすることと、お出かけすることだとどちらが多いですか？';if(/食べ物|お店/.test(t))return '好きな食べ物や、最近行ってよかったお店ってありますか？';if(/エリア/.test(t))return '普段ご飯に行くときは、どのあたりが行きやすいですか？';if(/通話/.test(t))return 'もしよかったら、今度少しだけ通話してみませんか？';if(/候補日|食事に誘う/.test(t))return 'よかったら今度ご飯に行きませんか？来週あたりはいかがですか？';if(/深掘り/.test(t))return 'それを好きになったきっかけって何かあったんですか？';if(/自分の話/.test(t))return '自分も最近そういうことがあって、結構好きなんです。';if(/質問を連続/.test(t))return 'ちなみに、他にはどんなことが好きですか？';return t+'。';}
function replyToChoice(w,choice,m){return scriptReply(w,choice,m)||'そうなんですね！もう少し聞いてみたいです。'}

function depthStats(id){let d=state.depth[id]||{surface:0,middle:0,deep:0,risk:0};return {surface:Math.min(100,d.surface*25),middle:Math.min(100,d.middle*25),deep:Math.min(100,d.deep*25),risk:d.risk||0};}
function classifyDepth(text){const t=String(text||'').replace(/\s/g,'');if(/過去の恋愛|元恋人|元彼|元カノ|結婚観|結婚したい|将来どう|家族|家庭環境|トラウマ|弱み|本音|人生観|不安|悩み|つらかった|傷ついた|恋愛遍歴/.test(t))return 'deep';if(/価値観|大切にしている|仕事のやりがい|仕事観|学生時代|友達|きっかけ|好きになった理由|こだわり|理想の|どんな人|趣味を始めた|休日の過ごし方|考え方/.test(t))return 'middle';return 'surface';}
function depthAdvice(id){let d=depthStats(id);if(d.risk)return '深い話題が少し早い可能性があります。いったん相手の返答を受け止め、答えやすい話題に戻しましょう。';if(d.surface<50)return 'まずはプロフィールの共通点や食べ物・休日など、相手が短く返しやすい話題から。質問を重ねず、自分の好みも一言添えましょう。';if(d.middle<50)return '共通点が見えたら、好きになったきっかけや普段の過ごし方を一段だけ深掘り。相手も質問や自己開示を返してくれるか確認しましょう。';if(d.deep<50)return '深い話題は必須ではありません。相手からも本音や価値観を話してくれる場合に限り、無理のない範囲で触れましょう。';return '話題の深さは十分です。深掘りを続けるより、相手の反応に合わせて会う・通話など次の段階へ進めるか考えましょう。'}
function depthResult(id){let d=depthStats(id);return `<div class="side-card"><h3>会話の深さ・踏み込み度</h3><p class="section-note">深い話題の数ではなく、信頼と相互の自己開示に合わせられているかを見ます。</p>${depthNames.map((n,i)=>{let v=[d.surface,d.middle,d.deep][i];return `<div class="metric-row"><span>${n}</span><strong>${v}%</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${v}%"></div></div>`}).join('')}<div class="tip">${depthAdvice(id)}</div>${d.risk?`<p class="section-note" style="color:#d66b83">踏み込み過多のサイン：${d.risk}回。相手の反応が薄いときは話題を戻しましょう。</p>`:''}</div>`;}
function conversationAnalysis(id){const msgs=state.chats[id]||[],mine=msgs.filter(m=>m.from==='me'),txt=mine.map(m=>m.text||''),all=txt.join(' '),count=mine.length,avg=count?txt.reduce((n,s)=>n+s.length,0)/count:0,questions=(all.match(/[?？]/g)||[]).length,hasFood=/ご飯|ごはん|食事|ランチ|ディナー|カフェ|スイーツ|肉|魚|寿司|焼肉|イタリアン|居酒屋|お酒|飲み/.test(all),hasArea=/どの辺|どのあたり|エリア|駅|沿線|場所|新宿|渋谷|横浜|池袋|吉祥寺|町田|府中|調布/.test(all),hasInvite=/会いませんか|会いましょう|行きませんか|行きましょう|ご一緒|デート|今度.*(行|食)/.test(all),hasConcrete=/明日|明後日|今週|来週|[月火水木金土日]曜|[0-9０-９]+日|ランチ|夜ご飯|お茶/.test(all),self=/僕は|自分は|私は|自分も|僕も|私も|実は/.test(all),empathy=/わかる|分かります|大変|お疲れ|いいですね|楽しそう|素敵ですね|たしかに/.test(all),deepEarly=mine.some((m,i)=>i<2&&classifyDepth(m.text)==='deep'),ease=Math.max(10,Math.min(100,82-(avg>100?Math.min(28,(avg-100)*.25):0)-(questions>count+1?12:0)-(avg>180?12:0)+(self?4:0))),comfort=Math.max(10,Math.min(100,58+(self?12:0)+(empathy?10:0)+(count>=2?6:0)-(deepEarly?24:0))),leadership=Math.max(10,Math.min(100,35+(hasFood?14:0)+(hasArea?14:0)+(hasInvite?22:0)+(hasConcrete?12:0)+(count>=2?5:0)));let next='';const last=msgs.at(-1);if(!count)next='最初の一通は、プロフィールの雰囲気やセンスを軽く褒め、共通点を一言添えて、会ってみたい意図を自然に伝えます。';else if(last?.from==='them'&&/忙し|予定|難し|その日は|無理/.test(last.text||''))next='断りを否定せず受け止め、別日を1〜2候補だけ出しましょう。理由を問い詰めず、相手の都合に合わせる姿勢も大切です。';else if(last?.from==='them'&&/もう少し|メッセージ|仲良く/.test(last.text||''))next='会うことを急かさず、短い通話を提案するか、相手が安心できる範囲で話す時間を作りましょう。';else if(hasInvite&&hasConcrete)next='誘いの方向性は伝わっています。相手の返答を待ち、OKなら日時・場所を具体化。曖昧なら選びやすい候補を2つに絞ります。';else if(!hasFood)next='共通点を細かく掘り下げすぎず、好きな食べ物や行ってみたい店を軽く聞いて、デートの話題につなげましょう。';else if(!hasArea)next='食の好みが分かったら、普段出かけるエリアや行きやすい駅を一つ聞きましょう。';else if(!hasInvite)next='お店・食べ物とエリアが見えたら、雑談を引き延ばさず、具体的な提案に進めるタイミングです。';else next='相手の返答に合わせて日程を調整しましょう。予定が先になる場合は、必要に応じて通話で安心感を作ります。';const st=state.stage[id]||{},scriptFit=Math.max(0,Math.min(100,Math.round(55+(st.scriptScore||0))));return {count,avg:Math.round(avg),ease,comfort,leadership,scriptFit,hasFood,hasArea,hasInvite,hasConcrete,deepEarly,next};}
function adviceCard(id){const a=conversationAnalysis(id);return `<div class="side-card"><h3>次の一手・メッセージ診断</h3><p class="section-note">動画の考え方をもとに、返信のしやすさ・安心感・デートへの進め方を確認します。実際の成功率ではなく練習用の目安です。</p><div class="metric-row"><span>返信しやすさ</span><strong>${a.ease}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.ease}%"></div></div><div class="metric-row"><span>安心感・相互性</span><strong>${a.comfort}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.comfort}%"></div></div><div class="metric-row"><span>デートへの段取り</span><strong>${a.leadership}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.leadership}%"></div></div><div class="metric-row"><span>相手別シナリオ適合度</span><strong>${a.scriptFit}/100</strong></div><div class="progress-wrap"><div class="progress-fill" style="width:${a.scriptFit}%"></div></div><div class="tip">${a.next}</div><p class="section-note">送信回数：${a.count}回 ／ 平均文字数：${a.avg}文字。目安は5ラリー前後ですが、相手の反応や安心感を優先します。</p></div>`;}
function library(){return head('REFERENCE / LEARNING','参考動画','共有された文字起こしの内容を、会話診断・採点・アドバイスに反映しています。',`<button class="btn btn-outline" id="addResource">＋ 動画を追加</button>`)+`<section class="section-card"><h3 class="section-title">今回の動画から反映した考え方</h3><div class="depth-guide"><div><b>01 返信しやすさ</b><p>短く要点を伝え、質問を重ねない。共通点は軽く触れ、細かく掘り下げすぎない。</p></div><div><b>02 安心感と相互性</b><p>砕けすぎない敬語、相手の温度感に合わせたリアクション、自分の話も返す自己開示。</p></div><div><b>03 デートへの段取り</b><p>食べ物・店の好みとエリアを自然に把握し、情報が揃ったら具体的に誘う。</p></div></div><p class="section-note">文字起こしの誤変換は前後の文脈で補って整理しています。動画内の主張をそのまま正解として固定せず、相手の意思・安心感・断る自由を優先する形に調整しています。</p></section><section class="section-card"><h3 class="section-title">5ラリーを目安にした会話の流れ</h3><div class="depth-guide"><div><b>1. 初回メッセージ</b><p>挨拶・プロフィールへの具体的な一言・共通点・会う意図を自然に伝える。</p></div><div><b>2. アイスブレイク</b><p>相手の返答に合わせて短くリアクションし、食べ物や好きな店の話題へ。</p></div><div><b>3. 情報を集める</b><p>行きたい店や食の好み、普段出かけるエリア・駅を確認する。</p></div><div><b>4. 具体的に誘う</b><p>店・場所・日程の候補を出す。断られたら別日を一度提案する。</p></div><div><b>5. 約束を整える</b><p>予定を確認し、必要なら短い通話で安心感を作る。連絡先交換は双方が望む場合だけ。</p></div></div><p class="section-note">5ラリーは目安です。返信が遅い・短い・迷っている場合に、回数だけを理由に誘いを急がせることはしません。</p></section><section class="section-card"><h3 class="section-title">採点・アドバイスの仕組み</h3><ul class="section-note"><li>返信しやすさ：文章の長さ、質問の数、返答の負担を確認</li><li>安心感・相互性：自己開示、共感、相手の温度感への合わせ方を確認</li><li>デートへの段取り：食の好み、エリア、具体的な誘い・日程候補を確認</li><li>会話の深さ：表面層・中間層・深層を別軸で記録し、深掘りの早さも確認</li></ul><p class="section-note">現在はキーワードや文章量を使ったルールベースの練習用評価です。実際の人間の感情やマッチング成功率を正確に予測するものではありません。</p></section><section class="section-card"><h3 class="section-title">登録済みの参考動画（${state.resources.length}）</h3>${state.resources.map(r=>`<div class="resource-row"><div class="resource-icon">▶</div><div class="resource-content"><strong>${r.title}</strong><span>${r.category}</span><p>${r.memo}</p><a href="${r.url}" target="_blank" rel="noopener">YouTubeで動画を見る ↗</a></div></div>`).join('')}</section>`}

function render(){let view={home,interests,talks,mypage,likes,library}[state.page]||home;$('#app').innerHTML=view();$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));}
function openModal(html){$('#modalRoot').innerHTML=`<div class="modal" role="dialog" aria-modal="true">${html}</div>`}
function closeModal(){$('#modalRoot').innerHTML=''}
function detail(id){let w=women.find(x=>x.id===id),c=common(w),fit=compatibility(w);openModal(`<div class="modal-head"><h2>プロフィール</h2><button class="close" data-close>×</button></div><div class="detail-hero"><img src="${photo(w)}"><div class="detail-info"><h2>${w.name} <span class="age">${w.age}歳</span></h2><div class="location">${w.area} ・ ${w.job} ・ ${w.height} ・ ${w.schedule}</div><p>${w.bio}</p><div class="tags">${w.topics.map(t=>`<span class="tag ${c.includes(t)?'common':''}">${t}</span>`).join('')}</div></div></div><div class="divider"></div><div class="metric-row"><span>共通する話題</span><strong>${c.length} 個</strong></div><div class="metric-row"><span>会話相性スコア（仮想）</span><strong style="color:#df6b8c">${score(w)}%</strong></div><p class="section-note">性格タイプ：${w.personality}<br>${w.history}<br>美術・デザイン：${w.background}<br>見た目：${w.appearance}</p><div class="tip">${fitNote(w)}</div><div class="tip">会話のきっかけ：${w.intro}</div><div style="display:flex;gap:8px;margin-top:17px"><button class="btn btn-primary" style="flex:1" data-like="${id}">♡ いいね！</button><button class="btn btn-outline" data-startchat="${id}">トークを始める</button></div>`)}
function like(id){if(!state.liked.includes(id))state.liked.push(id);state.stage[id]={...(state.stage[id]||{}),matched:true};if(!state.matched.includes(id))state.matched.push(id);state.chats[id]??=[];render();toast('マッチングしました！トークを始めましょう');}
function chat(id){state.current=id;state.page='talks';render();renderChat(id)}
function renderChat(id){let w=women.find(x=>x.id===id),msgs=state.chats[id]||[],p=progress(w),pc=pct(w),m=moodState(id),st=state.stage[id]||{},choices=choiceOptions(w,id),callReady=st.talk>=3&&m.guard<=55&&m.safety>=48&&m.interest>=45&&!st.call&&!st.closed;$('#app').innerHTML=head('MESSAGE / CONVERSATION',w.name+'さんとのトーク','相手の反応を見ながら、会話を選びましょう。',`<div class="chat-actions-top">${moodView(id)}<button class="btn btn-outline" id="callStart" ${callReady?'':'disabled'}>${st.call?'通話クリア済み':callReady?'通話フェーズへ ↗':'通話はもう少し安心感が必要'}</button></div>`)+`<div class="conversation-layout"><section class="chat-panel"><div class="chat-header"><img src="${photo(w)}"><div><strong>${w.name} <span class="age">${w.age}歳</span></strong><small>オンライン ・ ${w.personality}</small></div></div><div class="chat-body" id="chatBody">${msgs.length?msgs.map(m=>`<div class="bubble ${m.from==='me'?'me':'them'}">${escapeHtml(m.text)}<span class="time">${m.from==='me'?'送信済み':'既読'}</span></div>`).join(''):`<div class="bubble them">マッチングありがとうございます！よろしくお願いします☺️<span class="time">既読</span></div>`}${st.closed?'<div class="tip">この相手とのシミュレーションは終了しました。進捗をリセットすると最初からやり直せます。</div>':''}</div>${st.closed?'':`<div class="choice-area"><div class="choice-heading">次の返信を選んでください <span>相手ごとの会話台本に沿って反応・評価が変化</span></div><div class="choice-grid">${choices.map((c,i)=>`<button class="choice" data-messagechoice="${i}">${c.text}</button>`).join('')}</div></div>`}</section><aside><div class="side-card"><div class="side-card-title-row"><h3>会話の進捗</h3><button class="reset-progress" data-reset-progress="${id}">個別リセット</button></div><div class="result-score" style="font-size:32px">${pc}%</div><div class="progress-wrap"><div class="progress-fill" style="width:${pc}%"></div></div>${stageNames.map((n,i)=>`<div class="metric-row"><span>${n}</span><strong>${p[i]}%</strong></div>`).join('')}${st.call?'<p class="section-note">通話：クリア</p>':callReady?'<p class="section-note">通話：開始可能</p>':'<p class="section-note">通話：安心感・警戒心の条件を満たすと解放</p>'}</div><div class="side-card"><h3>会話アシスト</h3><p class="section-note">選択肢は相手の性格と内面状態に応じて変わります。</p>${suggestions(w).map(s=>`<div class="suggestion">${s}</div>`).join('')}</div>${depthResult(id)}${adviceCard(id)}<div class="side-card"><h3>相手別シナリオ</h3><strong>${personaScripts[w.id]?.label||w.style}</strong><p class="section-note">${personaGoals[w.id]||''}</p><p class="section-note">${({1:'カフェ・写真の話から共通点を作り、仕事の話は相手の興味に合わせて少しだけ。',2:'勤務の不規則さを理解し、返信頻度や日程を急かさず安心感を作る。',3:'音楽・服の話でテンポよく盛り上がり、好みの店やエリアへつなぐ。',4:'急に距離を詰めず、映画や読書の話を重ねて信頼を作る。',5:'旅行先や食の具体的な話から、店選びと日程調整へ自然に進む。',6:'ゲームやイラストの話を具体的に聞き、自分の趣味も少し共有する。',7:'ハンドメイドやカフェの話に共感し、明るいテンポで会話する。',8:'美術館・展示・デザインの視点を交換し、落ち着いた会話から誘う。'})[w.id]}</p><div class="tip">共通点：${common(w).join('、')||'まだありません'}<br>見た目：${w.appearance}</div></div></aside></div>`;$(' #callStart'.trim()).onclick=()=>{if(callReady)call(id);else toast('もう少しメッセージで安心感を作りましょう')};$('#chatBody').scrollTop=$('#chatBody').scrollHeight;$$('[data-messagechoice]').forEach(b=>b.onclick=()=>chooseMessage(id,Number(b.dataset.messagechoice)));$$('#moodOpen').forEach(b=>b.onclick=()=>moodModal(id));$$('[data-reset-progress]').forEach(b=>b.onclick=()=>resetProgressPrompt(id));}
function escapeHtml(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function escapeAttr(s){return escapeHtml(s).replace(/"/g,'&quot;')}
function suggestions(w){let a=conversationAnalysis(w.id),c=common(w),pool=[];if(!a.count){pool.push('プロフィールの雰囲気が素敵だと思いました。共通点もあって嬉しいです！');pool.push('マッチングありがとうございます。仲良くなったらご飯でも行きましょう！');}else if(!a.hasFood){pool.push('好きな食べ物ってありますか？');pool.push('最近行ってよかったお店ありますか？');}else if(!a.hasArea){pool.push('普段ご飯に行くときはどの辺が多いですか？');pool.push('行きやすい駅やエリアってありますか？');}else if(!a.hasInvite){pool.push('そのお店気になります。今度一緒に行きませんか？');pool.push('よかったら今度ご飯行きましょう！');}else{pool.push('今週末か来週のどちらかで都合いい日はありますか？');pool.push('難しければ別の日でも大丈夫です！');}if(c.length)pool.push(`共通の「${c[0]}」も気になります。自分も好きです！`);pool.push('自分もそういうの好きです。');return [...new Set(pool)].slice(0,4);}
function sendMessage(id,text){let w=women.find(x=>x.id===id);state.depth[id]??={surface:0,middle:0,deep:0,risk:0};let layer=classifyDepth(text),d=state.depth[id],rapport=(state.stage[id]?.talk||0)+(state.stage[id]?.call?3:0);if(layer==='surface')d.surface++;if(layer==='middle'){if(rapport>=1)d.middle++;else d.risk++;}if(layer==='deep'){if(rapport>=4)d.deep++;else d.risk++;}state.chats[id]??=[];state.chats[id].push({from:'me',text});state.stage[id]??={matched:true,talk:0,call:false,date:false};state.stage[id].talk=Math.min(5,(state.stage[id].talk||0)+1);renderChat(id);setTimeout(()=>{state.chats[id].push({from:'them',text:reply(w,text)});renderChat(id);toast('返信が届きました')},600)}
function reply(w,text){let c=common(w),talk=state.stage[w.id]?.talk||1,hit=c.find(t=>text.includes(t));if(hit)return `わあ、${hit}好きなんですね！私も好きです☺️ ${hit==='旅行'?'最近はどこか行きましたか？':'どんなところが好きですか？'}`;if(/好き|趣味|休み|休日/.test(text))return `そうですね！色々ありますよ〜！ ${w.intro}`;if(/会う|デート|ごはん|ご飯|カフェ/.test(text))return talk>=3?'いいですね！もう少しお話しして、ぜひ行ってみたいです☺️':'お誘い嬉しいです！もう少しメッセージでお話しできたら嬉しいです。';if(talk>=4)return 'それ面白いですね！話していると楽しいです☺️ よかったら今度通話してみませんか？';return ['いいですね！それは初めて聞きました！','わかります、私もそういうの好きです☺️','そうなんですね！もう少し詳しく聞きたいです！','たしかに！ちなみに休日は何していることが多いですか？'][Math.floor(Math.random()*4)]}
function call(id){let w=women.find(x=>x.id===id),m=moodState(id),st=state.stage[id]||{};if(st.closed||!(st.talk>=3&&m.guard<=55&&m.safety>=48&&m.interest>=45)){toast('通話を始めるには、もう少し安心感が必要です');return;}state.callSessions??={};state.callSessions[id]={round:0,limit:6,good:0,bad:0};renderCall(id);}
function callChoices(w,id){let m=moodState(id),r=state.callSessions?.[id]?.round||0;if(m.guard>=55)return ['相手の話を遮らず、まず聞く','自分の話を長く続ける','恋愛観を詳しく聞く','相手の反応を確認して話題を変える'];if(r<2)return ['メッセージで話した趣味をもう少し話す','最近あった小さな出来事を共有する','仕事やプライベートを細かく質問する','相手の話に相づちだけして終える'];if(r<4)return ['相手の考えを一つだけ聞き、自分の考えも話す','相手の話に共感して少し自己開示する','過去の恋愛や結婚観を聞く','沈黙が怖くて質問を続ける'];return ['一緒に行けそうな場所の話を軽くする','会って話すのも楽しそうと自然に伝える','今すぐ会う日を決めようと迫る','相手がどう感じているかを聞いてみる'];}
function renderCall(id){let w=women.find(x=>x.id===id),c=state.callSessions[id],round=c.round,choices=callChoices(w,id);openModal(`<div class="modal-head"><h2>30分通話シミュレーション</h2><button class="close" data-close>×</button></div><div class="call-screen"><img src="${photo(w)}"><h2>${w.name}</h2><p>通話中 ・ 30分の想定</p><div class="call-timer">残りラリー：${c.limit-round} / 6</div><div class="progress-wrap"><div class="progress-fill" style="width:${round/c.limit*100}%"></div></div><p>相手の反応を見ながら、会話を選んでください。</p></div><div style="margin-top:16px"><p class="section-note">踏み込みすぎず、安心感と会話意欲を育てましょう。</p><div class="choice-grid">${choices.map((x,i)=>`<button class="choice" data-callchoice="${i}">${x}</button>`).join('')}</div></div>`);$('[data-callchoice]').forEach(b=>b.onclick=()=>callChoice(id,Number(b.dataset.callchoice)));}function callChoice(id,index){let w=women.find(x=>x.id===id),m=moodState(id),st=state.stage[id],c=state.callSessions[id],choice=callChoices(w,id)[index];if(!c||!choice)return;let good=/聞く|共有|共感|自己開示|軽く|自然に|確認して/.test(choice),bad=/細かく質問|過去の恋愛|質問を続ける|迫る|長く続ける/.test(choice);if(good){m.safety+=6;m.interest+=5;m.affection+=3;m.guard=Math.max(0,m.guard-6);c.good++;}if(bad){m.safety-=9;m.interest-=8;m.affection-=4;m.guard+=13;c.bad++;}for(const k of ['safety','interest','affection','guard'])m[k]=Math.max(0,Math.min(100,m[k]));c.round++;state.chats[id]??=[];state.chats[id].push({from:'them',text:m.guard>=65?'そうなんですね。そろそろ時間も大丈夫ですか？':good?'それ、わかります。話しやすいですね。':'そうなんですね。'});if(m.guard>=78||m.interest<=18){st.closed=true;st.closeReason='call_cutoff';m.hidden='通話中に距離を置きたいと感じ、会話を続ける気持ちがなくなった';finishCall(id,false,true);return;}if(c.round>=c.limit){let passed=m.safety>=58&&m.interest>=55&&m.guard<=42&&m.affection>=48&&c.good>=4&&c.bad<=1;if(passed){st.call=true;m.interest=Math.min(100,m.interest+8);m.affection=Math.min(100,m.affection+6);m.hidden='通話して安心感が増し、実際に会ってみたいと思っている';}else if(m.guard>=65||m.interest<30){st.closed=true;st.closeReason='call_cutoff';m.hidden='通話を通して相性が合わないと感じ、見切っている';}finishCall(id,passed,st.closed);return;}renderCall(id);}
function finishCall(id,passed,closed){let w=women.find(x=>x.id===id),m=moodState(id),c=state.callSessions[id];openModal(`<div class="modal-head"><h2>通話結果</h2><button class="close" data-close>×</button></div><div style="text-align:center;padding:18px"><div class="result-score" style="font-size:28px">${passed?'通話クリア！':closed?'関係終了':'今回はクリアならず'}</div><p class="section-note">${passed?'会話のテンポと安心感が合い、実際に会ってみたいと思ってもらえました。':closed?'踏み込み方や会話の相性から、相手が関係を続けない判断をしました。':'もう少し安心感を作る必要がありました。メッセージで関係を整えましょう。'}</p><div class="tip">30分想定・${c.round}ラリー ／ 安心感 ${m.safety}% ／ 警戒度 ${m.guard}%</div>${passed?'<button class="btn btn-primary" style="margin-top:16px" data-nextdate="'+id+'">デートの日程を決める</button>':closed?'<p class="section-note">この相手とのやりとりは終了です。進捗を個別リセットすると再挑戦できます。</p>':'<button class="btn btn-outline" style="margin-top:16px" data-continuechat="'+id+'">メッセージに戻る</button>'}</div>`);}
function dateInvite(id){let w=women.find(x=>x.id===id),m=moodState(id),st=state.stage[id]||(state.stage[id]={matched:true,talk:0,call:false,date:false}),accepted=m.guard<=38&&m.safety>=58&&m.interest>=52&&m.affection>=48&&(st.call||st.talk>=4);if(accepted){st.date=true;m.hidden='実際に会ってみたいと思い、日程を調整したい';state.chats[id]??=[];state.chats[id].push({from:'them',text:'いいですね！予定を調整しますね。この日付はどうですか？'});openModal(`<div class="modal-head"><h2>日程調整へ</h2><button class="close" data-close>×</button></div><p>${w.name}さんから候補日が届きました。</p><div class="tip">会う約束が成立しました。候補日を確認して日程を決めましょう。</div><button class="btn btn-primary" style="margin-top:16px" data-finish="${id}">約束を確認する</button>`);}else{st.closed=true;st.closeReason='date_declined';m.hidden='今回は会う意思がなく、予定を理由に丁寧に断っている';state.chats[id]??=[];state.chats[id].push({from:'them',text:'今月は予定がいっぱい詰まっちゃってて、ごめんなさい。'});openModal(`<div class="modal-head"><h2>お誘いへの返答</h2><button class="close" data-close>×</button></div><p class="section-note">${w.name}さんから丁寧な返信がありました。</p><div class="tip">「今月は予定がいっぱい」という返答は、今回は会う意思がない間接的なお断りとして扱います。追いメッセージで挽回するルートはありません。</div><button class="btn btn-outline" style="margin-top:16px" data-continuechat="${id}">会話履歴を見る</button></div>`);}}
function resetProgressPrompt(id){let w=women.find(x=>x.id===id);openModal(`<div class="modal-head"><h2>会話の進捗をリセット</h2><button class="close" data-close>×</button></div><p>${w.name}さんとの会話履歴・好意・安心感・警戒度・通話結果・進捗を初期状態に戻します。</p><p class="section-note">この相手だけが対象です。他の相手の進捗には影響しません。</p><button class="btn btn-outline" data-close>キャンセル</button><button class="btn btn-primary" style="margin-left:8px" data-confirm-reset="${id}">リセットする</button>`);}
function resetProgress(id){delete state.stage[id];delete state.mood[id];delete state.chats[id];delete state.depth[id];delete state.callCount[id];if(state.callSessions)delete state.callSessions[id];state.stage[id]={matched:true,talk:0,call:false,date:false};state.mood[id]={affection:35,safety:42,interest:48,guard:18,hidden:'まだ様子を見ている'};closeModal();chat(id);toast('この相手の進捗をリセットしました');}
function addResource(){openModal(`<div class="modal-head"><h2>参考動画を追加</h2><button class="close" data-close>×</button></div><div class="field"><label>動画タイトル</label><input id="rTitle" placeholder="動画のタイトル"></div><div class="field"><label>YouTubeなどのURL</label><input id="rUrl" placeholder="https://youtu.be/..."></div><div class="field"><label>カテゴリ</label><input id="rCategory" placeholder="会話・プロフィール・デートなど"></div><div class="field"><label>内容メモ</label><input id="rMemo" placeholder="参考にしたいポイント"></div><button class="btn btn-primary" id="saveResource">追加する</button>`)}
function userSettings(){openModal(`<div class="modal-head"><h2>あなたのプロフィール</h2><button class="close" data-close>×</button></div><div class="form-row"><div class="field"><label>ニックネーム</label><input id="uName" value="${escapeHtml(state.user.name)}"></div><div class="field"><label>年齢（19〜34歳）</label><input id="uAge" type="number" min="19" max="34" value="${state.user.age}"></div></div><div class="form-row"><div class="field"><label>居住地</label><input id="uArea" value="${escapeHtml(state.user.area)}"></div><div class="field"><label>職業</label><input id="uJob" value="${escapeHtml(state.user.job)}" placeholder="会社員・印刷系・イベントスタッフ・デザイナーなど"></div></div><div class="form-row"><div class="field"><label>休日のタイプ</label><select id="uSchedule"><option value="土日休み" ${state.user.schedule==='土日休み'?'selected':''}>土日休み</option><option value="シフト制" ${state.user.schedule==='シフト制'?'selected':''}>シフト制</option></select></div><div class="field"><label>美術・デザインとの関わり</label><select id="uBackground"><option value="特になし" ${state.user.background==='特になし'?'selected':''}>特になし</option><option value="美大生・美大出身" ${state.user.background==='美大生・美大出身'?'selected':''}>美大生・美大出身</option><option value="服飾専門学生・出身" ${state.user.background==='服飾専門学生・出身'?'selected':''}>服飾専門学生・出身</option><option value="美術に少し興味あり" ${state.user.background==='美術に少し興味あり'?'selected':''}>美術に少し興味あり</option></select></div></div><div class="field"><label>趣味タグ（複数選択可）</label><div class="interest-grid">${['アート・デザイン','絵を描く','ハンドメイド','美術館','ファッション'].map(t=>`<label class="tag"><input type="checkbox" name="uArtTag" value="${t}" ${(state.user.artTags||[]).includes(t)?'checked':''}> ${t}</label>`).join('')}</div></div><button class="btn btn-primary" id="saveUser">保存する</button>`)}
document.addEventListener('click',e=>{let t=e.target.closest('button,[data-profile],[data-chat]');if(!t)return;if(t.dataset.page){state.page=t.dataset.page;render()}if(t.dataset.profile)detail(Number(t.dataset.profile));if(t.dataset.detail)detail(Number(t.dataset.detail));if(t.dataset.like)like(Number(t.dataset.like));if(t.dataset.filter){state.filter=t.dataset.filter;render()}if(t.dataset.topic){let x=t.dataset.topic;state.selectedTopics=state.selectedTopics.includes(x)?state.selectedTopics.filter(a=>a!==x):[...state.selectedTopics,x];render()}if(t.dataset.chat)chat(Number(t.dataset.chat));if(t.dataset.suggest)toast('会話の選択肢から返信を選んでください');if(t.dataset.startchat){let id=Number(t.dataset.startchat);closeModal();if(!state.matched.includes(id))state.matched.push(id);state.stage[id]??={matched:true,talk:0};chat(id)}if(t.id==='editInterests'){state.page='interests';render()}if(t.id==='addResource')addResource();if(t.id==='saveResource'){let title=$('#rTitle').value.trim(),url=$('#rUrl').value.trim();if(!title||!(url.startsWith('https://')||url.startsWith('http://'))){toast('タイトルと正しいURLを入力してください');return}state.resources.push({id:Date.now(),title,url,category:$('#rCategory').value||'その他',memo:$('#rMemo').value||'メモなし'});localStorage.setItem('matchlab_resources',JSON.stringify(state.resources));closeModal();render();toast('参考動画を追加しました')}if(t.id==='editUser'||t.id==='openSettings')userSettings();if(t.id==='saveUser'){const age=Number($('#uAge').value)||27;if(age<19||age>34){toast('年齢は19〜34歳で設定してください');return}state.user={...state.user,name:$('#uName').value||'Yuki',age,area:$('#uArea').value,job:$('#uJob').value,schedule:$('#uSchedule').value,background:$('#uBackground').value,artTags:$('input[name="uArtTag"]:checked').map(x=>x.value)};closeModal();render();toast('プロフィールを保存しました')}if(t.hasAttribute('data-close'))closeModal();if(t.id==='moodOpen')moodModal(state.current);if(t.dataset.confirmReset)resetProgress(Number(t.dataset.confirmReset));if(t.dataset.nextdate)dateInvite(Number(t.dataset.nextdate));if(t.dataset.continuechat){let id=Number(t.dataset.continuechat);closeModal();chat(id)}if(t.dataset.finish){let id=Number(t.dataset.finish);closeModal();state.page='mypage';render();toast(women.find(w=>w.id===id).name+'さんとのデートが確約しました！')}});
$('#openSettings').addEventListener('click',userSettings);
render();
